def find_seq():
    n=12
    length=2*n
    seq=[0]*length
    def backtrack(v):
        if v==0:
            return True
        for i in range(length):
            j=i+v+1
            if j<length and seq[i]==0 and seq[j]==0:
                seq[i]=seq[j]=v
                if backtrack(v-1):
                    return True
                seq[i]=seq[j]=0
        return False
    if backtrack(n):
        return seq
    return None

